def seed_sfs(apps, schema_editor):
    GuidelineCategory = apps.get_model('debt_app', 'GuidelineCategory')
    ExpenditureGuideline = apps.get_model('debt_app', 'ExpenditureGuideline')

    for row in GUIDELINES:
        group_name = row['category_group_name'].strip()
        group = None
        if group_name:
            group, _ = GuidelineCategory.objects.get_or_create(
                name=group_name,
                defaults={'sort_order': 0},
            )

        defaults = {
            'label': row['label'],
            'category_group': group,
            'sort_order': int(row['sort_order']),
            'min': bool(row['min']),
            'max': bool(row['max']),
            'formula': row.get('formula', ''),
            'below_action': row.get('below_action', ''),
            'above_action': row.get('above_action', ''),
            'mismatch_action': row.get('mismatch_action', ''),
            'notes': row.get('notes', ''),
        }
        for field in NUMERIC_FIELDS:
            raw = row.get(field, '0.00')
            try:
                defaults[field] = Decimal(str(raw))
            except Exception:
                defaults[field] = Decimal('0.00')

        ExpenditureGuideline.objects.update_or_create(
            category=row['category'],
            defaults=defaults,
        )


